&lt;ul&gt;
&lt;li&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&lt;span class=&quot;TextRun SCXW51270415 BCX8&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW51270415 BCX8&quot;&gt;Leadership and health of the Backend Engineering skill community&lt;/span&gt;&lt;/span&gt; &lt;/span&gt;&lt;/li&gt;
