&lt;li&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&lt;span class=&quot;TextRun SCXW51270415 BCX8&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW51270415 BCX8&quot;&gt;Champion the vision and execution of the backend components of the Dragos&lt;/span&gt;&lt;/span&gt; &lt;span class=&quot;TextRun SCXW51270415 BCX8&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW51270415 BCX8&quot;&gt;Platform&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&lt;span class=&quot;TextRun SCXW51270415 BCX8&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW51270415 BCX8&quot;&gt;Foster a strong technical community by developing close relationships amongst&lt;/span&gt;&lt;/span&gt; &lt;span class=&quot;TextRun SCXW51270415 BCX8&quot; lang=&quot;EN-US&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW51270415 BCX8&quot;&gt;Engineering Leaders&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
